<section class="panel book-panel"><a href="/admin/books/requests">← جميع الطلبات</a><h2>طلب نشر كتاب · <?=e($request['writer_name'])?></h2><p>رقم الطلب <?=(int)$request['id']?> · أُرسل <?=e($request['created_at'])?> · الحالة <?=e($request['status'])?></p>
<form method="post" action="/admin/books/requests/update" class="book-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$request['id']?>"><label>حالة الطلب<select name="status"><?php foreach(['pending'=>'جديد','reviewing'=>'قيد المراجعة','negotiating'=>'تفاوض','cancelled'=>'ملغى','completed'=>'مكتمل'] as $value=>$label):?><option value="<?=e($value)?>" <?=$request['status']===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>ملاحظة إدارية خاصة<textarea name="admin_note" rows="3"><?=e((string)$request['admin_note'])?></textarea></label><button class="btn btn-primary">حفظ حالة الطلب</button></form></section>
<section class="panel book-panel"><h2>نسخ الاتفاق</h2><p>تظل النسخ السابقة محفوظة. إرسال نسخة جديدة يلغي صلاحية موافقة النسخة السابقة للنشر.</p>
<?php foreach($agreements as $a):?><article class="book-agreement-row"><strong>النسخة <?=(int)$a['version']?> · <?=e($a['status'])?></strong><span><?=e($a['created_at'])?> · <?=e($a['fee'])?> <?=e($a['currency'])?> · الدفع: <?=e($a['payment_status'])?></span><a href="/admin/books/agreements/<?=(int)$a['id']?>">معاينة رابط الكاتب</a><?php if($a['status']==='accepted'):?><form method="post" action="/admin/books/agreements/payment"><?=csrf_field()?><input type="hidden" name="agreement_id" value="<?=(int)$a['id']?>"><label>حالة الدفع<select name="payment_status"><option value="pending" <?=$a['payment_status']==='pending'?'selected':''?>>بانتظار التحقق</option><option value="verified" <?=$a['payment_status']==='verified'?'selected':''?>>تم التحقق</option><option value="not_required" <?=$a['payment_status']==='not_required'?'selected':''?>>غير مطلوب</option></select></label><input name="payment_reference" maxlength="255" value="<?=e((string)($a['payment_reference']??''))?>" placeholder="Payment reference"><button class="btn btn-ghost">تحديث</button></form><?php endif;?></article><?php endforeach; ?>
<?php if($request['active_slot']):?><h3>إعداد عرض جديد</h3><form method="post" action="/admin/books/agreements/offer" class="book-form"><?=csrf_field()?><input type="hidden" name="request_id" value="<?=(int)$request['id']?>"><label>نص الاتفاق الكامل<textarea name="terms" rows="8" minlength="50" required placeholder="اكتب وصف الخدمة والالتزامات وحقوق الطرفين بوضوح"></textarea></label><div class="book-form-grid"><label>الرسوم الخاصة<input type="number" step="0.01" min="0" name="fee" required></label><label>العملة<input name="currency" value="USD" maxlength="3" required></label><label>بداية الخدمة<input type="date" name="service_start" required></label><label>نهاية الخدمة<input type="date" name="service_end" required></label></div><label>شروط الدفع<textarea name="payment_terms" rows="2"></textarea></label><label>نطاق الترويج<textarea name="promo_scope" rows="2"></textarea></label><label>حقوق الكاتب والتراخيص<textarea name="rights_terms" rows="2"></textarea></label><label>شروط الإلغاء<textarea name="cancellation_terms" rows="2"></textarea></label><label class="book-check"><input type="checkbox" name="allow_home" value="1"> السماح بالترويج في الصفحة الرئيسية ضمن الاتفاق</label><label class="book-check"><input type="checkbox" name="listing_after_expiry" value="1"> يستمر عرض الكتاب بعد انتهاء فترة التسويق وفق الاتفاق</label><button class="btn btn-primary" onclick="return confirm('هل تريد إرسال هذه النسخة من الاتفاق إلى الكاتب؟')">إرسال العرض للكاتب</button></form><?php endif;?></section>
